package org.marketreview.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public final class StockResearchChecks {
 private static int checks;private static void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 private static JSONObject sample()throws Exception{return new JSONObject().put("id","SH:stock:600001").put("name","测试公司").put("quote",new JSONObject().put("price",10.1).put("tradeDate","2026-10-11").put("tradeTime","15:00:00").put("source","本机真实测试源").put("cached",true)).put("capitalSnapshotMeta",new JSONObject().put("source","公开分类资金").put("checkedAt","2026-10-11T07:10:00Z").put("sourceTimeKnown",false).put("snapshot",new JSONObject().put("mainNet",0))).put("documents",new JSONArray().put(new JSONObject().put("id","doc-1").put("title","原文资料").put("text",String.join("",Collections.nCopies(600000,"长"))).put("verification","manuallyVerified").put("sourceUrl","https://example.test/original")));}
 private static JSONObject empty()throws Exception{return new JSONObject().put("schema","stock-research/v1").put("notes",new JSONArray()).put("snapshots",new JSONArray());}
 private static void model()throws Exception{JSONObject original=sample(),snapshot=StockResearchModel.snapshot("fixed","SH:stock:600001",original,"当时笔记","2026-10-12T00:00:00.000Z");check(StockResearchModel.canonical(snapshot.getJSONObject("bundle")).equals(StockResearchModel.canonical(original)),"full original freeze");original.getJSONObject("quote").put("price",999);check(snapshot.getJSONObject("bundle").getJSONObject("quote").getDouble("price")==10.1,"source object mutation cannot rewrite snapshot");boolean bad=false;try{StockResearchModel.identity("600001");}catch(Exception e){bad=true;}check(bad,"bare code rejected");bad=false;try{StockResearchModel.identity("SZ:stock:600001");}catch(Exception e){bad=true;}check(bad,"market mismatch rejected");bad=false;try{StockResearchModel.bundle("SZ:stock:000001",original);}catch(Exception e){bad=true;}check(bad,"host identity mismatch rejected");JSONObject portable=empty().put("snapshots",new JSONArray().put(snapshot));check(StockResearchModel.canonical(StockResearchModel.decode(portable.toString())).equals(StockResearchModel.canonical(portable)),"portable complete roundtrip");JSONObject duplicate=new JSONObject(portable.toString()).put("snapshots",new JSONArray().put(snapshot).put(snapshot));bad=false;try{StockResearchModel.decode(duplicate.toString());}catch(Exception e){bad=true;}check(bad,"duplicate snapshot rejects batch");JSONObject altered=new JSONObject(snapshot.toString()).put("note","不同笔记");check(StockResearchModel.preview(empty().put("snapshots",new JSONArray().put(altered)),portable).getJSONArray("conflicts").length()==1,"snapshot conflict preserved");check(StockResearchModel.overview(snapshot.getJSONObject("bundle")).contains("2026-10-11")&&StockResearchModel.overview(snapshot.getJSONObject("bundle")).contains("未提供"),"source times and missing data visible");}
 public static int run(Context c)throws Exception{checks=0;model();StockResearchStore store=new StockResearchStore(c,"stock-research-check-"+UUID.randomUUID()+".sqlite");try{JSONObject original=sample();final JSONObject[] opened={null};final String[] chart={null};StockResearchScreen screen=new StockResearchScreen(c,store,id->{JSONObject b=new JSONObject(original.toString());b.put("id",id);return b;},r->opened[0]=r,id->chart[0]=id);screen.setInstrument("SH:stock:600001");EditText note=screen.findViewWithTag("stockResearchNote");note.setText("未保存草稿");screen.refreshSources();check(note.getText().toString().equals("未保存草稿"),"refresh retains draft");screen.setInstrument("SZ:stock:000001");screen.setInstrument("SH:stock:600001");check(note.getText().toString().equals("未保存草稿"),"per-security draft retained");ListView docs=screen.findViewWithTag("stockResearchDocuments");docs.setItemChecked(0,true);docs.performItemClick(null,0,0);((Button)screen.findViewWithTag("stockResearchOpenSource")).performClick();check(StockResearchModel.canonical(opened[0]).equals(StockResearchModel.canonical(original.getJSONArray("documents").getJSONObject(0))),"exact original source callback");((Button)screen.findViewWithTag("stockResearchChart")).performClick();check(chart[0].equals("SH:stock:600001"),"full identity chart callback");JSONObject state=screen.saveState();StockResearchScreen reopened=new StockResearchScreen(c,store,id->{throw new IllegalStateException("must not fetch on restoration");},null,null);reopened.restoreState(state);check(((EditText)reopened.findViewWithTag("stockResearchNote")).getText().toString().equals("未保存草稿"),"reconstruction retains draft without fetch");check(((TextView)reopened.findViewWithTag("stockResearchOriginal")).getText().toString().contains("2026-10-11"),"reconstruction retains source vintage");store.saveNote("SH:stock:600001","其他页面更新",new JSONObject());((Button)reopened.findViewWithTag("stockResearchSaveNote")).performClick();check(store.note("SH:stock:600001").getString("text").equals("其他页面更新"),"stale note save protected");reopened.discardNote();check(((EditText)reopened.findViewWithTag("stockResearchNote")).getText().toString().equals("其他页面更新"),"explicit draft discard");screen.saveSnapshot();JSONObject snapshot=store.backup().getJSONArray("snapshots").getJSONObject(0);check(snapshot.getJSONObject("bundle").getJSONArray("documents").getJSONObject(0).getString("text").length()==600000,"long evidence complete in actual SQLite");original.getJSONObject("quote").put("price",999);screen.refreshSources();check(store.backup().getJSONArray("snapshots").getJSONObject(0).getJSONObject("bundle").getJSONObject("quote").getDouble("price")==10.1,"new quote never backfills history");JSONObject before=store.backup();screen.previewImport(before.toString());check(StockResearchModel.canonical(store.backup()).equals(StockResearchModel.canonical(before)),"preview no writes");screen.cancelImport();check(StockResearchModel.canonical(store.backup()).equals(StockResearchModel.canonical(before)),"cancel no writes");screen.previewImport(before.toString());store.saveNote("SZ:stock:000001","变化",new JSONObject());JSONObject changed=store.backup();screen.confirmImport();check(StockResearchModel.canonical(store.backup()).equals(StockResearchModel.canonical(changed)),"stale preview no write");screen.setDarkTheme(true);screen.setDarkTheme(false);return checks;}finally{store.close();}}
 public static void main(String[] args)throws Exception{checks=0;model();if(args.length>0){String input=new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8);JSONObject decoded=StockResearchModel.decode(input);check(decoded.getJSONArray("snapshots").getJSONObject(0).getJSONObject("bundle").getJSONArray("documents").getJSONObject(0).getString("text").length()==600000,"Qt export original complete on Java");if(args.length>1)Files.write(Paths.get(args[1]),decoded.toString().getBytes(StandardCharsets.UTF_8));}System.out.println("stock research Java pure: "+checks+" checks GREEN; Android native UI/store device pending root");}
}
